}

/vgpu-wgsl-std/hash/index.wgsl:
// Wellons lowbias32: https://github.com/skeeto/hash-prospector
export fn hashU32(value: u32) -> u32 {
  var hashed = value;
  hashed = (hashed ^ (hashed >> 16u)) * 0x7feb352du;
  hashed = (hashed ^ (hashed >> 15u)) * 0x846ca68bu;
  hashed = hashed ^ (hashed >> 16u);
  return hashed;
}

export fn pcg2d(value: vec2u) -> vec2u {
  // 2D multi-output variant cross-mixes with the LCG multiplier instead of pcg3d's y*z pattern.
  var hashed = value * 1664525u + 1013904223u;
  hashed.x = hashed.x + hashed.y * 1664525u;
  hashed.y = hashed.y + hashed.x * 1664525u;
  hashed = hashed ^ (hashed >> vec2u(16u));
  hashed.x = hashed.x + hashed.y * 1664525u;
  hashed.y = hashed.y + hashed.x * 1664525u;
  hashed = hashed ^ (hashed >> vec2u(16u));
  return hashed;
}

export fn pcg3d(value: vec3u) -> vec3u {
  var hashed = value * 1664525u + 1013904223u;
  hashed.x = hashed.x + hashed.y * hashed.z;
  hashed.y = hashed.y + hashed.z * hashed.x;
  hashed.z = hashed.z + hashed.x * hashed.y;
  hashed = hashed ^ (hashed >> vec3u(16u));
  hashed.x = hashed.x + hashed.y * hashed.z;
  hashed.y = hashed.y + hashed.z * hashed.x;
  hashed.z = hashed.z + hashed.x * hashed.y;
  hashed = hashed ^ (hashed >> vec3u(16u));
  return hashed;
}

export fn unitFloat(hash: u32) -> f32 {
  return f32(hash >> 8u) * (1.0 / 16777216.0);
}

export fn hash1(seed: f32) -> f32 {
  return unitFloat(hashU32(bitcast<u32>(seed)));
}

export fn hash2(seed: vec2f) -> vec2f {
  let hashed = pcg2d(bitcast<vec2u>(seed));
  return vec2f(unitFloat(hashed.x), unitFloat(hashed.y));
}

export fn hash3(seed: vec3f) -> vec3f {
  let hashed = pcg3d(bitcast<vec3u>(seed));
  return vec3f(unitFloat(hashed.x), unitFloat(hashed.y), unitFloat(hashed.z));
}

/vgpu-wgsl-std/light/index.wgsl:
export fn lambert(normal: vec3f, lightDirection: vec3f, lightColor: vec3f, intensity: f32) -> vec3f {
  let n = normalize(normal);
  let l = normalize(-lightDirection);
  return lightColor * max(dot(n, l), 0.0) * intensity;
}

/vgpu-wgsl-std/math/index.wgsl:
export fn saturate(value: f32) -> f32 {
  return clamp(value, 0.0, 1.0);
}

export fn clamp01(value: f32) -> f32 {
  return saturate(value);
}

export fn inverseLerp(rangeStart: f32, rangeEnd: f32, value: f32) -> f32 {
  let denominator = rangeEnd - rangeStart;
  if (denominator == 0.0) {
    return 0.0;
  }
  return (value - rangeStart) / denominator;
}

export fn remap(inMin: f32, inMax: f32, outMin: f32, outMax: f32, value: f32) -> f32 {
  let t = inverseLerp(inMin, inMax, value);
  return outMin + t * (outMax - outMin);
}

export fn safeNormalize2(value: vec2f, fallback: vec2f) -> vec2f {
  let lengthSquared = dot(value, value);
  if (lengthSquared <= 0.0) {
    return fallback;
  }
  return value * inverseSqrt(lengthSquared);
}

export fn safeNormalize3(value: vec3f, fallback: vec3f) -> vec3f {
  let lengthSquared = dot(value, value);
  if (lengthSquared <= 0.0) {
    return fallback;
  }
  return value * inverseSqrt(lengthSquared);
}

export fn safeNormalize4(value: vec4f, fallback: vec4f) -> vec4f {
  let lengthSquared = dot(value, value);
  if (lengthSquared <= 0.0) {
    return fallback;
  }
  return value * inverseSqrt(lengthSquared);
}

export fn rotate2d(value: vec2f, radians: f32) -> vec2f {
  let c = cos(radians);
  let s = sin(radians);
  return mat2x2f(c, s, -s, c) * value;
}

