// Shared, table-free gradient core for the gradient-noise families (perlin/, simplex/).
//
// Private module: it is intentionally absent from this package's `package.json` exports, so the
// only way in is a relative import from a sibling noise module
// (`import { gradDot3 } from "../internal/gradient.wgsl";`). The declarations still carry `export`
// because the resolver keys its import graph off that literal token
// (packages/wgsl/src/runtime/parser.ts) -- `export` here means "importable by a relative sibling",
// not "public API".
//
// Determinism contract (locked by tests/noise-gradient.test.ts):
//   * no `array<...>` anywhere: permutation/gradient tables cost shader text in every consumer and
//     backends expand or spill them anyway, buying nothing over a few `select`s.
//   * no `sin`/`cos`/`sqrt`/`inverseSqrt`/`pow` anywhere: their accuracy is implementation-defined
//     (WGSL allows several ulp), so an angle-based gradient would drift per driver and make golden
//     tests flaky. Everything below is `+ - * select` plus the exactly specified u32 hash ops, so
//     *which* gradient a cell gets is bit-identical on every backend.
//
// References (algorithms, no code copied): Perlin 2002 "Improving Noise" (quintic fade, 12
// cube-edge gradients), Perlin 2001 / Gustavson "Simplex noise demystified".
import { pcg2d, pcg3d } from "@vgpu/wgsl-std/hash";

// 1 / sqrt(2), spelled as a literal because `sqrt` is banned above.
export const noiseInvSqrt2: f32 = 0.7071067811865476;

// Gradient selector: pcg2d/pcg3d over the bit pattern of the integer cell (same idiom as
// voronoi2d/voronoi3d), giving a 2^32-cell period instead of the folklore period-289 float hash.
export fn gradIndex2(cell: vec2i) -> u32 { return pcg2d(bitcast<vec2u>(cell)).x & 7u; }

// 12 gradients out of 32 bits: bias is 4/2^32 ~= 1e-9.
export fn gradIndex3(cell: vec3i) -> u32 { return pcg3d(bitcast<vec3u>(cell)).x % 12u; }

// 8 unit gradients. index 0..3 -> (1,0) (-1,0) (0,1) (0,-1);  4..7 -> (+-1,+-1)/sqrt(2).
// Unit length keeps the 2D field's amplitude bound closed-form (raw sup |perlin2d| = 1/sqrt(2)).
export fn gradDot2(index: u32, d: vec2f) -> f32 {
  let axis = select(d.x, d.y, (index & 2u) != 0u);
  let axisDot = select(axis, -axis, (index & 1u) != 0u);
  let sx = select(d.x, -d.x, (index & 1u) != 0u);
  let sy = select(d.y, -d.y, (index & 2u) != 0u);
  return select(axisDot, noiseInvSqrt2 * (sx + sy), index >= 4u);
}

// Perlin's 12 cube-edge gradients (+-1,+-1,0) (+-1,0,+-1) (0,+-1,+-1), length sqrt(2): the dot
// product costs one add plus two negations, no multiplies.
// index/4 selects the component pair: 0 -> (x,y), 1 -> (x,z), 2 -> (y,z); bits 0/1 are the signs.
export fn gradDot3(index: u32, d: vec3f) -> f32 {
  let pair = index / 4u;
  let a = select(d.x, d.y, pair == 2u);
  let b = select(select(d.y, d.z, pair == 1u), d.z, pair == 2u);
  let sa = select(a, -a, (index & 1u) != 0u);
  let sb = select(b, -b, (index & 2u) != 0u);
  return sa + sb;
}

// Quintic fade 6t^5 - 15t^4 + 10t^3 (Perlin 2002): zero first *and* second derivative at the cell
// boundaries, so lattice seams stay invisible in derivatives (normals) too.
export fn noiseFade2(t: vec2f) -> vec2f { return t * t * t * (t * (t * 6.0 - 15.0) + 10.0); }
export fn noiseFade3(t: vec3f) -> vec3f { return t * t * t * (t * (t * 6.0 - 15.0) + 10.0); }

/vgpu-wgsl-std/noise/perlin/index.wgsl:
// Improved Perlin noise (Perlin 2002: quintic fade + cube-edge gradient set) in 2D/3D, plus the
// amplitude-normalized FBM that wraps each one.
//
// Numeric contract -- the published field *is* the API here, so treat every constant below as
// frozen (locked by tests/perlin.test.ts):
//   * range is a guaranteed open (-1, 1), never clipped. The trilinear/quintic blend is a convex
//     combination of the corner dot products, so |value| <= max_i |g_i . d_i|; the raw suprema are
//     1/sqrt(2) = 0.7071067812 (2D, attained at f = (0.5, 0.5)) and 1.0363538112 (3D), and the
//     normalizers below are strictly *below* 1/sup, so the bound is a proof rather than an
//     observation. Do not "fix" them toward the folkloric 2.2x of webgl-noise's cnoise: that
//     value provably exceeds 1 and forces every consumer to clamp.
//   * typical amplitude is much smaller than the bound (sigma ~= 0.305 in 2D, 0.260 in 3D):
//     consumers should `remap`, not `saturate`.
//   * exactly 0 at every integer lattice point (all corner offsets are zero vectors there, and
//     fade(0) = 0), which is the highest-value regression signal for a fade or corner-offset bug.
//
// Determinism contract, inherited from ../internal/gradient.wgsl: no lookup tables, no
// sin/cos/sqrt/inverseSqrt/pow, integer pcg hashing only -- so *which* gradient a cell gets is
// bit-identical on every backend and reproducible by the f32-exact TS reference in
// tests/perlin.test.ts.
//
// Reference (algorithm only, no code copied): Ken Perlin, "Improving Noise", SIGGRAPH 2002.
import { gradDot2, gradDot3, gradIndex2, gradIndex3, noiseFade2, noiseFade3 } from "../internal/gradient.wgsl";

// 1 / 0.7071067812 = 1.41421356..., truncated *downward* so the range stays strictly inside
// (-1, 1): max |perlin2d| = 0.99996.
const perlinNormalize2: f32 = 1.4142;
// 1 / 1.0363538112 = 0.96491..., with ~1% margin against residual error in the numeric sup search:
// max |perlin3d| = 0.99956.
const perlinNormalize3: f32 = 0.9645;

export fn perlin2d(position: vec2f) -> f32 {
  let base = floor(position);
  // vec2i(floor(p)) -- never vec2i(p): truncation toward zero would collapse the cells on both
  // sides of the origin into one, which is a visible seam for negative coordinates.
  let cell = vec2i(base);
  let f = position - base;
  let u = noiseFade2(f);
  let d00 = gradDot2(gradIndex2(cell), f);
  let d10 = gradDot2(gradIndex2(cell + vec2i(1, 0)), f - vec2f(1.0, 0.0));
  let d01 = gradDot2(gradIndex2(cell + vec2i(0, 1)), f - vec2f(0.0, 1.0));
  let d11 = gradDot2(gradIndex2(cell + vec2i(1, 1)), f - vec2f(1.0, 1.0));
  return perlinNormalize2 * mix(mix(d00, d10, u.x), mix(d01, d11, u.x), u.y);
}

export fn perlin3d(position: vec3f) -> f32 {
  let base = floor(position);
  let cell = vec3i(base);
  let f = position - base;
  let u = noiseFade3(f);
  let d000 = gradDot3(gradIndex3(cell), f);
  let d100 = gradDot3(gradIndex3(cell + vec3i(1, 0, 0)), f - vec3f(1.0, 0.0, 0.0));
  let d010 = gradDot3(gradIndex3(cell + vec3i(0, 1, 0)), f - vec3f(0.0, 1.0, 0.0));
  let d110 = gradDot3(gradIndex3(cell + vec3i(1, 1, 0)), f - vec3f(1.0, 1.0, 0.0));
  let d001 = gradDot3(gradIndex3(cell + vec3i(0, 0, 1)), f - vec3f(0.0, 0.0, 1.0));
  let d101 = gradDot3(gradIndex3(cell + vec3i(1, 0, 1)), f - vec3f(1.0, 0.0, 1.0));
  let d011 = gradDot3(gradIndex3(cell + vec3i(0, 1, 1)), f - vec3f(0.0, 1.0, 1.0));
  let d111 = gradDot3(gradIndex3(cell + vec3i(1, 1, 1)), f - vec3f(1.0, 1.0, 1.0));
  let x00 = mix(d000, d100, u.x);
  let x10 = mix(d010, d110, u.x);
  let x01 = mix(d001, d101, u.x);
  let x11 = mix(d011, d111, u.x);
  return perlinNormalize3 * mix(mix(x00, x10, u.y), mix(x01, x11, u.y), u.z);
}

// Fractal Brownian motion, amplitude-normalized: `sum / weight` with `weight` the sum of the
// amplitudes. That division is what keeps the (-1, 1) guarantee alive across octaves, because
// |sum| <= weight by construction.
//
// Both clamps are silent and deliberate:
//   * `octaves` in [1, 16] bounds the loop -- a dynamic count coming from a uniform could
//     otherwise hang the GPU;
//   * `gain` in [0, 1] keeps `weight` equal to the sum of |amplitude|, which the range proof needs
//     (a negative gain would cancel terms in `weight` while still adding magnitude to `sum`).
// `weight >= 1` always (the first amplitude is 1), so the division is never by zero.
//
// Free invariant, asserted by the tests: fbmPerlin2d(p, 1, lacunarity, gain) == perlin2d(p) exactly.
export fn fbmPerlin2d(position: vec2f, octaves: i32, lacunarity: f32, gain: f32) -> f32 {
  let count = clamp(octaves, 1, 16);
  let decay = clamp(gain, 0.0, 1.0);
  var sum = 0.0;
  var amplitude = 1.0;
  var weight = 0.0;
  var sample = position;
  for (var i = 0; i < count; i = i + 1) {
    sum = sum + amplitude * perlin2d(sample);
    weight = weight + amplitude;
    sample = sample * lacunarity;
    amplitude = amplitude * decay;
  }
  return sum / weight;
}

// Cost model: one perlin3d is 8 pcg3d hashes, so a 6-octave call is 48 -- prefer fbmPerlin2d when
// the third axis only carries animation.
export fn fbmPerlin3d(position: vec3f, octaves: i32, lacunarity: f32, gain: f32) -> f32 {
  let count = clamp(octaves, 1, 16);
  let decay = clamp(gain, 0.0, 1.0);
  var sum = 0.0;
  var amplitude = 1.0;
  var weight = 0.0;
  var sample = position;
  for (var i = 0; i < count; i = i + 1) {
    sum = sum + amplitude * perlin3d(sample);
    weight = weight + amplitude;
    sample = sample * lacunarity;
    amplitude = amplitude * decay;
  }
  return sum / weight;
}

/vgpu-wgsl-std/noise/simplex/index.wgsl:
// Simplex noise on the skewed simplicial lattice (Perlin 2001; Gustavson, "Simplex noise
// demystified"), re-derived on this package's integer pcg hashes -- no code copied, no permutation
// table, no period-289 float hash, and no `sqrt`/trig anywhere in the core (see
// ../internal/gradient.wgsl for the determinism contract this module inherits).
//
// Range is a *proof*, not an observation: the kernel sum is bounded by its measured supremum
// (0.0100802047 for 2D, 0.0130071572 for 3D) and the normalizers below sit just under 1/sup, so
// abs(simplex2d(p)) <= 0.98786 and abs(simplex3d(p)) <= 0.98854 for every finite input. Do not
// replace them with the folkloric webgl-noise scale factors, which exceed 1 and force consumers to
// clamp. sigma is ~0.533 (2D) / ~0.388 (3D): ~1.7x Perlin's, with ~2.5x the slope, so
// `simplex3d(p)` is a higher-frequency field than `perlin3d(p)` -- scale `p` by ~0.4-0.5 when
// migrating (see index.docs.md).
import { gradDot2, gradDot3, gradIndex2, gradIndex3 } from "../internal/gradient.wgsl";

// Skew/unskew constants, spelled as precomputed decimal literals because `sqrt` is banned in the
// core: its accuracy is implementation-defined, which would make the goldens driver-dependent.
const simplexF2: f32 = 0.36602540378443865;      // (sqrt(3) - 1) / 2
const simplexG2: f32 = 0.21132486540518713;      // (3 - sqrt(3)) / 6
const simplexG2Twice: f32 = 0.42264973081037427; // 2 * simplexG2
const simplexF3: f32 = 0.3333333333333333;       // 1 / 3
const simplexG3: f32 = 0.16666666666666666;      // 1 / 6
const simplexG3Twice: f32 = 0.3333333333333333;  // 2 * simplexG3
const simplexG3Thrice: f32 = 0.5;                // 3 * simplexG3

// Kernel radius^2 is 0.5, NOT the widespread 0.6 (Gustavson/webgl-noise canonical value):
// 0.6 measurably produces C0 cracks (max |dv| ~4.6e-5 to 9.5e-5 vs ~2.9e-8 to 4.8e-8 at 0.5,
// i.e. ~1000x worse) because its support radius (0.775) exceeds the 4-corner traversal's
// reach. See `simplexCrackDetector` in tests/simplex.test.ts -- do not "fix" this back to 0.6.
//
// Why 0.5 is exactly right rather than merely smaller: on the face where the corner ranking flips,
// the corner the traversal drops sits at squared distance >= 0.5 from the sample, with equality at
// the tightest point (2D: d = (simplexG2 - 0.5, 0.5), |d|^2 = 0.5 exactly). At radius^2 = 0.5 that
// dropped corner therefore contributes exactly 0 with a vanishing first and second derivative
// (t^4), so the field stays C2 across every simplex face. At 0.6 the same corner still carries
// t = 0.1, and dropping it is a discontinuity.
fn simplexKernel2(cell: vec2i, d: vec2f) -> f32 {
  let t = 0.5 - dot(d, d);
  if (t <= 0.0) { return 0.0; }
  let t2 = t * t;
  return t2 * t2 * gradDot2(gradIndex2(cell), d);
}

fn simplexKernel3(cell: vec3i, d: vec3f) -> f32 {
  let t = 0.5 - dot(d, d);
  if (t <= 0.0) { return 0.0; }
  let t2 = t * t;
  return t2 * t2 * gradDot3(gradIndex3(cell), d);
}

// 2D simplex: 3 corners of a triangle in the sheared lattice. `vec2i(base)` (never
// `vec2i(position)`) keeps negative coordinates correct, and there is no float `mod` anywhere --
// WGSL's `%` truncates toward the dividend, unlike GLSL's `mod`, which is how ported noise code
// silently breaks for p < 0.
export fn simplex2d(position: vec2f) -> f32 {
  let skew = (position.x + position.y) * simplexF2;
  let base = floor(position + vec2f(skew));
  let cell = vec2i(base);
  let unskew = (base.x + base.y) * simplexG2;
  let d0 = position - (base - vec2f(unskew));
  // Which of the two triangles of the sheared cell we are in: the ranking of d0's components.
  let second = select(vec2f(0.0, 1.0), vec2f(1.0, 0.0), d0.x > d0.y);
  let d1 = d0 - second + vec2f(simplexG2);
  let d2 = d0 - vec2f(1.0) + vec2f(simplexG2Twice);
  var total = simplexKernel2(cell, d0);
  total = total + simplexKernel2(cell + vec2i(second), d1);
  total = total + simplexKernel2(cell + vec2i(1, 1), d2);
  // raw sup = 0.0100802047, so 98.0 < 1/sup: abs(value) <= 0.98786, never clipped.
  return 98.0 * total;
}

// 3D simplex: 4 corners of a tetrahedron, i.e. half the 8 corners perlin3d needs (4 pcg3d hashes
// against Perlin's 8).
export fn simplex3d(position: vec3f) -> f32 {
  let skew = (position.x + position.y + position.z) * simplexF3;
  let base = floor(position + vec3f(skew));
  let cell = vec3i(base);
  let unskew = (base.x + base.y + base.z) * simplexG3;
  let d0 = position - (base - vec3f(unskew));

  // Traversal order = ranking of d0's components (the classic error-prone step). The six branches
  // are the six orderings of (x, y, z): `o1` steps along the largest component and `o2` adds the
  // second largest, so the pair encodes *which two* of the four tetrahedron corners are visited in
  // the middle. Do not "simplify" this into arithmetic on comparisons -- every collapsed variant
  // swaps a corner for at least one ordering, which the goldens and the crack detector catch but a
  // statistical test would not.
  var o1 = vec3f(0.0);
  var o2 = vec3f(0.0);
  if (d0.x >= d0.y) {
    if (d0.y >= d0.z)      { o1 = vec3f(1.0, 0.0, 0.0); o2 = vec3f(1.0, 1.0, 0.0); } // x >= y >= z
    else if (d0.x >= d0.z) { o1 = vec3f(1.0, 0.0, 0.0); o2 = vec3f(1.0, 0.0, 1.0); } // x >= z > y
    else                   { o1 = vec3f(0.0, 0.0, 1.0); o2 = vec3f(1.0, 0.0, 1.0); } // z > x >= y
  } else {
    if (d0.y < d0.z)       { o1 = vec3f(0.0, 0.0, 1.0); o2 = vec3f(0.0, 1.0, 1.0); } // z > y > x
    else if (d0.x < d0.z)  { o1 = vec3f(0.0, 1.0, 0.0); o2 = vec3f(0.0, 1.0, 1.0); } // y >= z > x
    else                   { o1 = vec3f(0.0, 1.0, 0.0); o2 = vec3f(1.0, 1.0, 0.0); } // y > x >= z
  }

  let d1 = d0 - o1 + vec3f(simplexG3);
  let d2 = d0 - o2 + vec3f(simplexG3Twice);
  let d3 = d0 - vec3f(1.0) + vec3f(simplexG3Thrice);
  var total = simplexKernel3(cell, d0);
  total = total + simplexKernel3(cell + vec3i(o1), d1);
  total = total + simplexKernel3(cell + vec3i(o2), d2);
  total = total + simplexKernel3(cell + vec3i(1, 1, 1), d3);
  // raw sup = 0.0130071572, so 76.0 < 1/sup: abs(value) <= 0.98854, never clipped.
  return 76.0 * total;
}

// Amplitude-normalized FBM: dividing by the sum of the amplitudes is what makes the (-1, 1)
// guarantee survive octaves (abs(sum) <= weight by construction, and weight >= 1 so the division is
// always safe). `octaves` is clamped to [1, 16] because an unbounded dynamic loop count is a
// GPU-hang risk, and `gain` to [0, 1] because a negative gain would break weight = sum of |a| and
// with it the range proof. Both clamps are silent and documented. Free invariant:
// `fbmSimplex2d(p, 1, lacunarity, gain)` is exactly `simplex2d(p)`.
export fn fbmSimplex2d(position: vec2f, octaves: i32, lacunarity: f32, gain: f32) -> f32 {
  let count = clamp(octaves, 1, 16);
  let decay = clamp(gain, 0.0, 1.0);
  var sum = 0.0;
  var amplitude = 1.0;
  var weight = 0.0;
  var sample = position;
  for (var i = 0; i < count; i = i + 1) {
    sum = sum + amplitude * simplex2d(sample);
    weight = weight + amplitude;
    sample = sample * lacunarity;
    amplitude = amplitude * decay;
  }
  return sum / weight;
}

export fn fbmSimplex3d(position: vec3f, octaves: i32, lacunarity: f32, gain: f32) -> f32 {
  let count = clamp(octaves, 1, 16);
  let decay = clamp(gain, 0.0, 1.0);
  var sum = 0.0;
  var amplitude = 1.0;
  var weight = 0.0;
  var sample = position;
  for (var i = 0; i < count; i = i + 1) {
    sum = sum + amplitude * simplex3d(sample);
    weight = weight + amplitude;
    sample = sample * lacunarity;
    amplitude = amplitude * decay;
  }
  return sum / weight;
}

